const t = $json || {};
const msg = t.message || null;
const chat = msg && msg.chat ? msg.chat : null;
const from = msg && msg.from ? msg.from : null;
const chat_id = (chat && chat.id !== undefined && chat.id !== null) ? String(chat.id) : '';
const from_id = (from && from.id !== undefined && from.id !== null) ? String(from.id) : '';
const text = (msg && typeof msg.text === 'string') ? msg.text.trim() : '';
const valid = !!(msg && chat && chat_id !== '');
return [{ json: {
  valid,
  chat_id,
  from_id,
  text,
  first_name: (from && from.first_name) || '',
  last_name: (from && from.last_name) || '',
} }];

const ev = $('Extract & Validate').first().json;
const cfg = $input.first().json || {};
const admin_chat_id = (cfg && cfg.config_value !== undefined && cfg.config_value !== null && String(cfg.config_value).trim() !== '')
  ? String(cfg.config_value).trim()
  : '';
const from_id = String(ev.from_id || '');
const is_admin = admin_chat_id !== '' && from_id === admin_chat_id;
return [{ json: {
  chat_id: ev.chat_id,
  from_id,
  text: ev.text,
  first_name: ev.first_name,
  last_name: ev.last_name,
  admin_chat_id,
  is_admin,
} }];

const ev = $('Build Context').first().json;
const row = $input.first().json || {};
const keys = Object.keys(row);
const expected = ['telegram_id','nombre_completo','departamento','puntos_lealtad'];
let missing = [];
if (keys.length > 0) { missing = expected.filter(c => !keys.includes(c)); }
const ok = missing.length === 0;
const error_text = ok ? '' : '⚠️ La hoja USUARIOS no tiene las columnas requeridas. Faltan: ' + missing.join(', ') + '. Corrige la hoja e intenta de nuevo.';
const exists = row.telegram_id !== undefined && row.telegram_id !== null && String(row.telegram_id) !== '';
const nombre_nuevo = ((ev.first_name || '') + ' ' + (ev.last_name || '')).trim() || 'amigo';
return [{ json: {
  chat_id: ev.chat_id,
  from_id: ev.from_id,
  ok,
  error_text,
  exists,
  nombre_existing: row.nombre_completo || '',
  nombre_nuevo,
} }];

const ev = $('Build Context').first().json;
const rows = $input.all().map(i => i.json).filter(r => r && Object.keys(r).length > 0);
const expected = ['numero','producto','precio','stock'];
const fmt = (p) => '$' + (Number(p) || 0).toLocaleString('es-CO', { maximumFractionDigits: 0 });
let text;
if (rows.length > 0) {
  const keys = Object.keys(rows[0]);
  const missing = expected.filter(c => !keys.includes(c));
  if (missing.length) {
    text = '⚠️ La hoja MENU no tiene las columnas requeridas. Faltan: ' + missing.join(', ') + '. Corrige la hoja e intenta de nuevo.';
    return [{ json: { chat_id: ev.chat_id, text } }];
  }
}
const disp = rows.filter(r => Number(r.stock) > 0);
if (disp.length === 0) {
  text = '📋 MENÚ\n\nLo sentimos, no hay productos disponibles en este momento.';
} else {
  text = '📋 MENÚ\n\n';
  for (const it of disp) {
    text += it.numero + '. ' + String(it.producto || '').trim() + ' - ' + fmt(it.precio) + ' (stock: ' + it.stock + ')\n';
  }
  text += '\nResponde con el número del producto que deseas comprar.';
}
return [{ json: { chat_id: ev.chat_id, text } }];

const ev = $('Build Context').first().json;
const s = $('Read Session (Conf)').first().json || {};
let cart = {};
try { cart = JSON.parse(s.carrito_temporal || '{}'); } catch (e) { cart = {}; }
return [{ json: {
  chat_id: ev.chat_id,
  from_id: ev.from_id,
  admin_chat_id: ev.admin_chat_id,
  numero: (cart.numero !== undefined && cart.numero !== null) ? String(cart.numero) : '',
  producto: cart.producto || '',
  precio: Number(cart.precio) || 0,
  cantidad: Number(cart.cantidad) || 0,
} }];

const ctx = $('Prepare Confirm').first().json;
const prod = $input.first().json || {};
const fmt = (v) => '$' + (Number(v) || 0).toLocaleString('es-CO', { maximumFractionDigits: 0 });
const numero = String(ctx.numero || '');
const cantidad = Number(ctx.cantidad) || 0;
const productExists = prod.numero !== undefined && prod.numero !== null && String(prod.numero) !== '' && String(prod.numero) === numero;
const stock = Number(prod.stock) || 0;
let ok = true; let error_text = '';
if (numero === '') { ok = false; error_text = '❌ No tienes un producto seleccionado. Escribe /menu para empezar.'; }
else if (cantidad <= 0) { ok = false; error_text = '❌ Aún no indicaste la cantidad. Responde con un número antes de confirmar.'; }
else if (!productExists) { ok = false; error_text = '❌ El producto ya no está disponible. Escribe /menu para ver el menú actualizado.'; }
else if (stock < cantidad) { ok = false; error_text = '❌ Stock insuficiente. Solo quedan ' + stock + ' unidad(es) de ' + (prod.producto || '') + '.'; }
const precio = Number(prod.precio) || Number(ctx.precio) || 0;
const total = precio * cantidad;
const producto = prod.producto || ctx.producto || 'Producto';
const id_pedido = 'PED-' + Date.now();
const now = new Date();
const fecha = now.toLocaleDateString('es-CO', { timeZone: 'America/Bogota' });
const hora = now.toLocaleTimeString('es-CO', { timeZone: 'America/Bogota', hour12: false });
const detalle = producto + ' x' + cantidad;
const confirm_text = '✅ ¡Pedido confirmado!\n\n🧾 Pedido: ' + id_pedido + '\n🛒 ' + detalle + '\n💵 Total: ' + fmt(total) + '\n📌 Estado: Recibido\n📅 ' + fecha + '   ⏰ ' + hora + '\n\n¡Gracias por tu compra! ☕';
const admin_text = '🔔 NUEVO PEDIDO\n\n🧾 ' + id_pedido + '\n👤 Cliente: ' + ctx.from_id + '\n🛒 ' + detalle + '\n💵 Total: ' + fmt(total) + '\n📌 Estado: Recibido\n📅 ' + fecha + '   ⏰ ' + hora + '\n\nUsa /estado ' + id_pedido + ' <estado> para actualizarlo.';
return [{ json: {
  ok, error_text, id_pedido,
  telegram_id: ctx.from_id, chat_id: ctx.chat_id, admin_chat_id: ctx.admin_chat_id,
  producto, cantidad, precio, total, fecha, hora, detalle,
  confirm_text, admin_text,
} }];

const ctx = $('Build Context').first().json;
const text = String(ctx.text || '').trim();
const admin_chat_id = ctx.admin_chat_id;
const parts = text.split(/\s+/);
const id_pedido = parts[1] || '';
const estado_raw = parts.slice(2).join(' ').trim();
const estados = [
  { c: 'Recibido', e: '📥' },
  { c: 'Preparando', e: '👨‍🍳' },
  { c: 'En camino', e: '🚗' },
  { c: 'Entregado', e: '✅' },
];
const norm = (s) => String(s || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().trim();
const match = estados.find(x => norm(x.c) === norm(estado_raw));
const valid = id_pedido.length > 0 && !!match;
const nuevo_estado = match ? match.c : '';
const emoji = match ? match.e : '';
const customer_text = valid ? ('📦 Actualización de tu pedido ' + id_pedido + '\n\nTu pedido ahora está: ' + emoji + ' ' + nuevo_estado) : '';
const admin_ok_text = valid ? ('✅ Estado actualizado.\n🧾 ' + id_pedido + '\n📌 ' + emoji + ' ' + nuevo_estado + '\n📨 Cliente notificado.') : '';
const invalid_text = '❌ Comando inválido.\n\nUso: /estado [id_pedido] [estado]\nEstados válidos: Recibido, Preparando, En camino, Entregado.';
return [{ json: {
  id_pedido, nuevo_estado, emoji, valid,
  admin_chat_id, chat_id: ctx.chat_id,
  customer_text, admin_ok_text, invalid_text,
} }];

const ev = $('Build Context').first().json;
const s = $('Read Session (Sel)').first().json || {};
let cart = {};
try { cart = JSON.parse(s.carrito_temporal || '{}'); } catch (e) { cart = {}; }
const cantidad = Number(ev.text) || 1;
cart.cantidad = cantidad;
const precio = Number(cart.precio) || 0;
const total = precio * cantidad;
const fmt = (v) => '$' + (Number(v) || 0).toLocaleString('es-CO', { maximumFractionDigits: 0 });
let ask = '🛒 ' + String(cart.producto || 'Producto').trim() + ' x' + cantidad + '\n';
ask += '💵 Subtotal: ' + fmt(total) + '\n\nEscribe /confirmar para completar tu pedido.';
return [{ json: {
  telegram_id: ev.from_id,
  chat_id: ev.chat_id,
  pantalla_actual: 'esperando_confirmacion',
  carrito_temporal: JSON.stringify(cart),
  ultimo_cambio: new Date().toISOString(),
  ask_text: ask,
} }];

const ev = $('Build Context').first().json;
const p = $input.first().json || {};
const fmt = (v) => '$' + (Number(v) || 0).toLocaleString('es-CO', { maximumFractionDigits: 0 });
const cart = { numero: p.numero, producto: p.producto, precio: Number(p.precio) || 0 };
let summary = '✅ Producto seleccionado:\n\n';
summary += '🛒 ' + String(p.producto || '').trim() + '\n';
summary += '💵 ' + fmt(p.precio) + '\n';
summary += '(stock disponible: ' + p.stock + ')\n\n';
summary += '¿Cuántas unidades deseas? Responde con un número.';
return [{ json: {
  telegram_id: ev.from_id,
  chat_id: ev.chat_id,
  pantalla_actual: 'esperando_cantidad',
  carrito_temporal: JSON.stringify(cart),
  ultimo_cambio: new Date().toISOString(),
  summary_text: summary,
} }];
